+}
+
+#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
+async fn cancel_during_a_tool_call_stream_is_cancelled() {
+    let (res, calls) = cancel_after_20ms(vec![paigasus_helikon_core::ModelEvent::ToolCallDelta {
+        call_id: "c1".into(),
